// Shadow-only guard: reject anything that is not an explicit simulation bundle.
const body = $input.first().json.body || {};
const reject = (reason) => [{ json: { ok: false, reject: true, reason } }];
if (body.shadowMode !== true) return reject('not_shadow_mode');
if (body.executionMode !== 'simulation-only') return reject('not_simulation_only');
if (!body.idempotencyKey || !String(body.idempotencyKey).startsWith('shadow-')) return reject('bad_idempotency_key');
if (!body.sessionId || !body.agentId) return reject('missing_ids');
// Production-mutation vocabulary must never appear in a bundle.
const raw = JSON.stringify(body).toLowerCase();
for (const banned of ['create-ticket', 'submit-ticket', 'update-call-data', 'callback-campaign', 'patientphone', 'patientdob']) {
  if (raw.includes(banned)) return reject('production_vocabulary_present:' + banned);
}
return [{ json: { ok: true, reject: false, idempotencyKey: body.idempotencyKey, sessionId: body.sessionId, agentId: body.agentId, verdict: body.bundle?.verdict ?? '', summary: JSON.stringify(body.bundle?.summary ?? {}).slice(0, 4000), ts: new Date().toISOString() } }];
